-- ----------------------------------------------
-- INTERACTION_HISTORY
-- ----------------------------------------------
DROP TABLE IF EXISTS interaction_history;
CREATE TABLE interaction_history (
    interaction_id BIGINT,
    cif TEXT,
    interaction_date DATE,
    channel TEXT,
    purpose TEXT,
    notes TEXT,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    source_system TEXT,
    PRIMARY KEY (interaction_id)
);
CREATE INDEX idx_interaction_history_cif ON interaction_history(cif);
COMMIT;
